import java.util.*;

class Solution {
  public String[] spellchecker(String[] wordlist, String[] queries) {
    Set<String> exact = new HashSet<>();
    Map<String, String> lower = new HashMap<>(), vowel = new HashMap<>();
    for (String w : wordlist) {
      exact.add(w);
      lower.putIfAbsent(w.toLowerCase(), w);
      vowel.putIfAbsent(norm(w), w);
    }
    String[] out = new String[queries.length];
    for (int i = 0; i < queries.length; i++) {
      String q = queries[i];
      if (exact.contains(q)) out[i] = q;
      else if (lower.containsKey(q.toLowerCase())) out[i] = lower.get(q.toLowerCase());
      else out[i] = vowel.getOrDefault(norm(q), "");
    }
    return out;
  }

  private String norm(String s) {
    s = s.toLowerCase();
    StringBuilder b = new StringBuilder();
    for (char c : s.toCharArray()) b.append("aeiou".indexOf(c) >= 0 ? '*' : c);
    return b.toString();
  }
}
